import zipfile,html,textwrap,json,os,sys
from pathlib import Path
from xml.etree import ElementTree as ET
from openpyxl import load_workbook
esc=lambda x:html.escape(str(x),quote=True)
def docx(path,paras):
 content=''.join('<w:p><w:pPr><w:spacing w:after="160"/></w:pPr><w:r><w:t xml:space="preserve">'+esc(x)+'</w:t></w:r></w:p>' for x in paras)
 with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
  z.writestr('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>')
  z.writestr('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>')
  z.writestr('word/document.xml','<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+content+'<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:bottom="1134" w:left="1134" w:right="1134"/></w:sectPr></w:body></w:document>')
def pdf(path,pages):
 objects=[b'<< /Type /Catalog /Pages 2 0 R >>',b'',b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];ids=[]
 for title,paras in pages:
  lines=[title,'']
  for p in paras:lines+=textwrap.wrap(p,94)+['']
  lines=lines[:64]
  stream='BT /F1 10 Tf 45 795 Td 12 TL\n'
  for line in lines:stream+='('+line.replace('\\','\\\\').replace('(','\\(').replace(')','\\)')+') Tj T*\n'
  stream+='ET';stream=stream.encode('cp1252','replace');pid=len(objects)+1;sid=pid+1;ids.append(pid)
  objects += [f'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents {sid} 0 R >>'.encode(),f'<< /Length {len(stream)} >>\nstream\n'.encode()+stream+b'\nendstream']
 objects[1]=('<< /Type /Pages /Count %d /Kids [%s] >>'%(len(ids),' '.join(f'{i} 0 R' for i in ids))).encode();out=bytearray(b'%PDF-1.4\n');offset=[0]
 for i,o in enumerate(objects,1):offset.append(len(out));out+=f'{i} 0 obj\n'.encode()+o+b'\nendobj\n'
 xref=len(out);out+=f'xref\n0 {len(objects)+1}\n0000000000 65535 f \n'.encode()
 for o in offset[1:]:out+=f'{o:010d} 00000 n \n'.encode()
 out+=f'trailer\n<< /Size {len(objects)+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF'.encode();Path(path).write_bytes(out)
def pptx(path,pages):
 ns='http://schemas.openxmlformats.org/presentationml/2006/main';a='http://schemas.openxmlformats.org/drawingml/2006/main';rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
 with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
  overrides='<Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>'
  for i in range(1,len(pages)+1):overrides+=f'<Override PartName="/ppt/slides/slide{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>'
  z.writestr('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'+overrides+'</Types>')
  z.writestr('_rels/.rels',f'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="{rel}/officeDocument" Target="ppt/presentation.xml"/></Relationships>')
  ids=''.join(f'<p:sldId id="{255+i}" r:id="rId{i}"/>' for i in range(1,len(pages)+1))
  z.writestr('ppt/presentation.xml',f'<p:presentation xmlns:p="{ns}" xmlns:a="{a}" xmlns:r="{rel}"><p:sldIdLst>{ids}</p:sldIdLst><p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>')
  z.writestr('ppt/_rels/presentation.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+''.join(f'<Relationship Id="rId{i}" Type="{rel}/slide" Target="slides/slide{i}.xml"/>' for i in range(1,len(pages)+1))+'</Relationships>')
  for i,(title,paras) in enumerate(pages,1):
   body=''.join(f'<a:p><a:pPr marB="180000"/><a:r><a:rPr lang="en-US" sz="{2600 if k==0 else 1800}"/><a:t>{esc(t)}</a:t></a:r></a:p>' for k,t in enumerate([title]+paras))
   z.writestr(f'ppt/slides/slide{i}.xml',f'<p:sld xmlns:p="{ns}" xmlns:a="{a}" xmlns:r="{rel}"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id="2" name="Content"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="600000" y="400000"/><a:ext cx="10900000" cy="6000000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr><p:txBody><a:bodyPr wrap="square"/><a:lstStyle/>{body}</p:txBody></p:sp></p:spTree></p:cSld></p:sld>')
def result_pages(w):
 val=lambda s,c:w[s][c].value
 euro=lambda x:f'EUR {x:,.0f}' if isinstance(x,(float,int)) else str(x)
 return [('Student housing near VUB - investment decision',['Valuation: 29 October 2026. All figures nominal, pre-tax. Hypothetical site; no investment commitment.',f'Base project NPV: {euro(val("KPI_Dashboard","B2"))}. Project IRR: {val("KPI_Dashboard","B3"):.2%}.',f'Best constructed case NPV: {euro(val("Optimization","I2"))}. Selected NPV including no investment: {euro(val("Optimization","I3"))}.',str(val('Optimization','I7'))]),('Evidence and assumptions',['VUB standard 2026-27 institutional room: EUR 449.30/month including services. Brukot city ordinary-room median: EUR 590/month including charges. Private residence rents can be higher. These do not establish achieved rent for this site.','Brussels property-specific reference rent and planning review remain outstanding. The 20% excessive-rent presumption is qualified, not a universal price ceiling.','Construction EUR 2200/m2, demand 125 students, elasticity 1.2, land EUR 1.5m and 4.5% borrowing are editable management assumptions, not observed site data.']),('Business model and reliability',['Demand = 125 * demand shock * exp[-1.2*(rent/590 - 1)]. Occupied market rooms are capped at available rooms. Affordable rooms have separate prices and demand.','One period of development at year 0, twenty annual operating periods. NOI, replacement capex, debt amortization and terminal proceeds are separate. No corporate income taxes or tax shields.','Project discount rate 8%, equity hurdle 10%, common nominal growth 2%, exit cap 5.5% are unverified investor assumptions.']),('Managerial decisions - optimization and break-even',[f'Capacity and rent: systematic integer search finds best built {val("Optimization","I5"):,.0f} rooms, EUR {val("Optimization","I6"):,.0f}/month market rent. No-build remains available.',f'Maximum viable development spend at base operating economics: {euro(val("KPI_Dashboard","B16"))}. This is a ceiling, not a minimum required investment.',f'Undiscounted payback including sale: {val("KPI_Dashboard","B6")}; discounted payback: {val("KPI_Dashboard","B7")}.','Optimization uses capacities 40-140, EUR 5 rent steps, floor area and budget limits, and 10% affordable rooms. A continuous global optimum and plot-specific feasibility are not claimed.']),('Sensitivity and uncertainty',[f'Largest NPV swing over stated input envelopes: {val("Sensitivity_Analysis","B6")}. Comparing different ranges does not establish statistical causality.',f'1000 independent persistent triangular trials: mean NPV {euro(val("Monte_Carlo","I2"))}, P5 {euro(val("Monte_Carlo","I6"))}, P95 {euro(val("Monte_Carlo","I7"))}.',f'Probability of negative NPV: {val("Monte_Carlo","I8"):.1%}. This probability is conditional on subjective distributions, not a forecast calibrated to market history.','Cost factor 0.85/1/1.25; demand 0.75/1/1.15; opex 0.9/1/1.2; exit cap 4.5/5.5/7%. Triangular distributions reflect judgmental min/mode/max. Correlated adverse shocks and delays could worsen tails.']),('Affordability, sustainability and recommendation',[f'Affordable share {val("KPI_Dashboard","B12"):.1%}. Affordable rent EUR 449.30 including services. At least 10% is an explicit management constraint; eligibility assumed means-tested enrolled students.',f'Illustrative annual operational carbon: {val("KPI_Dashboard","B13"):,.1f} tonnes; energy {val("KPI_Dashboard","B14"):,.0f} kWh. Energy and emissions factors are not measured or certified.','Obtain a secured site, itemized construction bids, achievable rent survey, pre-letting evidence, planning/fire/EPC review and lender terms before approval. Reject projects with nonpositive NPV or failed constraints.','Do not force profitability. Student review of financial assumptions, sources and formula logic remains required.']),('References and implementation limits',[r[2].value for r in w['Sources'].iter_rows(min_row=2)]+['Formula-based sensitivity and finite grid optimization implemented; native Excel Data Tables and Solver not configured. Cached values supplied by a local supported-function evaluator. Microsoft Excel/Word/PowerPoint desktop execution not performed. Report and slides are concise text-based documents; charts are in the workbook.'])]
if __name__=='__main__':
 w=load_workbook('model.xlsx',data_only=True);pages=result_pages(w);docx('Executive_Report.docx',[s for title,ps in pages for s in [title]+ps]);Path('intermediate/report_content.json').write_text(json.dumps(pages,indent=2));print('Word report saved')
